apiVersion: apps/v1
kind: Deployment
metadata:
  name: forecast-service
  namespace: gridcast
  labels: { app.kubernetes.io/name: forecast-service, app.kubernetes.io/component: model-serving, app.kubernetes.io/part-of: gridcast }
  annotations:
    gridcast.dev/description: "Serves the production load model"
spec:
  replicas: 1
  revisionHistoryLimit: 10
  # Two copies of a large model do not fit on the node, so this service replaces in place
  # (no surge): a rollout briefly takes it down, and a bad rollout keeps it down.
  strategy: { type: RollingUpdate, rollingUpdate: { maxUnavailable: 1, maxSurge: 0 } }
  selector: { matchLabels: { app.kubernetes.io/name: forecast-service } }
  template:
    metadata:
      labels: { app.kubernetes.io/name: forecast-service, app.kubernetes.io/component: model-serving, app.kubernetes.io/part-of: gridcast }
    spec:
      terminationGracePeriodSeconds: 20
      securityContext: { runAsNonRoot: true, runAsUser: 10001, seccompProfile: { type: RuntimeDefault } }
      containers:
        - name: forecast-service
          imagePullPolicy: Always  # dev registry: tags may be rebuilt
          image: gridcast/forecast-service
          args: ["serve", "forecast-service"]
          ports: [{ name: http, containerPort: 8080 }]
          envFrom:
            - configMapRef: { name: gridcast-runtime }
            - configMapRef: { name: forecast-config }
          env:
            - name: GRIDCAST_DB_USER
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: db-app, key: username } }
            - name: GRIDCAST_DB_PASSWORD
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: db-app, key: password } }
            - name: S3_ACCESS_KEY
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: s3-credentials, key: access_key } }
            - name: S3_SECRET_KEY
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: s3-credentials, key: secret_key } }
            - name: K8S_POD_NAME
              valueFrom: { fieldRef: { fieldPath: metadata.name } }
            - name: K8S_NAMESPACE
              valueFrom: { fieldRef: { fieldPath: metadata.namespace } }
            - name: K8S_NODE_NAME
              valueFrom: { fieldRef: { fieldPath: spec.nodeName } }
            - { name: K8S_DEPLOYMENT_NAME, value: forecast-service }
          readinessProbe: { httpGet: { path: /readyz, port: http }, periodSeconds: 10, failureThreshold: 3 }
          livenessProbe: { httpGet: { path: /healthz, port: http }, periodSeconds: 20, timeoutSeconds: 5, failureThreshold: 3 }
          startupProbe: { httpGet: { path: /healthz, port: http }, periodSeconds: 5, failureThreshold: 60 }
          resources:
            requests: { cpu: 200m, memory: 160Mi }
            limits: { cpu: "1", memory: 160Mi }
          securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: [ALL] } }
          volumeMounts: [{ name: tmp, mountPath: /tmp }]
      volumes: [{ name: tmp, emptyDir: {} }]
---
apiVersion: v1
kind: Service
metadata: { name: forecast-service, namespace: gridcast, labels: { app.kubernetes.io/name: forecast-service, app.kubernetes.io/part-of: gridcast } }
spec:
  type: NodePort
  selector: { app.kubernetes.io/name: forecast-service }
  ports: [{ name: http, port: 80, targetPort: http, nodePort: 30081 }]
